"""Differential tester: fast engine vs naive reference."""
import json
import random
import sys

sys.path.insert(0, '/workspace/submission')
sys.path.insert(0, '/workspace/dev')
import ref as refmod
from adapter import execute_batch


def random_partition(U, count):
    inner = sorted(random.sample(range(1, U), min(count, U - 1))) if U > 1 else []
    return [0] + inner + [U]


def make_run(rng_seed, allow=True):
    random.seed(rng_seed)
    M = random.randint(1, 4)
    L = random.randint(1, 3)
    U = random.randint(2, 30)
    R = random.randint(1, min(5, U - 1)) if U > 1 else 1
    borders = random_partition(U, R)
    kind = random.choice(['fifo', 'sp', 'sff', 'wfq'])
    flows = list(range(random.randint(1, 5)))
    if kind == 'sp':
        policy = {'kind': 'sp', 'levels': [[f, random.randrange(0, U)] for f in flows]}
    elif kind == 'wfq':
        policy = {'kind': 'wfq', 'weights': [[f, random.randint(1, 64)] for f in flows]}
    else:
        policy = {'kind': kind}
    spec = {'banks': M, 'load_balancers': L,
            'fifo_bytes': random.choice([1, 4, 10, 40, 1000]),
            'pifo_bytes': random.choice([1, 4, 10, 40, 1000]),
            'refill_batch': random.randint(1, 4),
            'sample_period': random.choice([1, 2, 3, 7, 1000]),
            'borders': borders, 'policy': policy, 'events': []}
    n = random.randint(0, 60)
    next_id = 0
    names = []
    for i in range(n):
        choice = random.random()
        if choice < 0.42:
            spec['events'].append(['enqueue', next_id, random.choice(flows),
                                   random.randint(1, 8), random.randrange(0, U)])
            next_id += 1
        elif choice < 0.62:
            spec['events'].append(['dequeue', random.randint(1, 3)])
        elif choice < 0.67:
            spec['events'].append(['sample'])
        elif choice < 0.72:
            spec['events'].append(['repartition', random_partition(U, random.randint(1, min(6, U - 1)))])
        elif choice < 0.78:
            spec['events'].append(['cancel', random.randrange(0, max(next_id + 2, 3))])
        elif choice < 0.84:
            spec['events'].append(['inspect', random.randrange(0, max(next_id + 2, 3))])
        elif choice < 0.87 and kind == 'wfq':
            spec['events'].append(['weight', random.choice(flows), random.randint(1, 64)])
        elif choice < 0.94:
            name = random.randrange(0, 3)
            spec['events'].append(['save', name])
            names.append(name)
        else:
            if names:
                spec['events'].append(['restore', random.choice(names)])
            else:
                spec['events'].append(['inspect', 0])
    return spec


def main():
    lo, hi = int(sys.argv[1]), int(sys.argv[2])
    bad = 0
    for seed in range(lo, hi):
        spec = make_run(seed)
        request = {'runs': [spec]}
        mine = json.loads(json.dumps(execute_batch(request)))
        theirs = json.loads(json.dumps(refmod.run_batch(request)))
        if mine != theirs:
            bad += 1
            print('SEED', seed, 'MISMATCH')
            if bad == 1:
                open('/workspace/dev/fail_%d.json' % seed, 'w').write(json.dumps(request))
                lg_a = mine['runs'][0]['log']
                lg_b = theirs['runs'][0]['log']
                for k in range(min(len(lg_a), len(lg_b))):
                    if lg_a[k] != lg_b[k]:
                        print(' first log diff at row', k)
                        print('  engine :', lg_a[k])
                        print('  ref    :', lg_b[k])
                        break
                else:
                    print(' log lengths', len(lg_a), len(lg_b))
                    print(' state engine', json.dumps(mine['runs'][0]['state']))
                    print(' state ref   ', json.dumps(theirs['runs'][0]['state']))
                return 1
    print('checked', hi - lo, 'seeds, mismatches:', bad)
    return 0 if bad == 0 else 1


if __name__ == '__main__':
    sys.exit(main())
